from pathlib import Path
p=Path(__file__).parents[1]/'src/app.js';s=p.read_text()
s=s.replace("accountPane:false,settings:","accountPane:false,authUser:null,authForm:null,authError:'',settings:")
s=s.replace("const persist=()=>storeSet('localStorage',KEY,JSON.stringify(profile));", """const persist=()=>{if(S.authUser){fetch('./api/profile',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(profile)}).catch(()=>{});}else storeSet('localStorage',KEY,JSON.stringify(profile));};
async function authRequest(endpoint,payload){const r=await fetch('./api/'+endpoint,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw Error(data.error||'Échec de connexion');return data;}
async function loadAccount(){if(location.protocol!=='http:'&&location.protocol!=='https:')return;try{const r=await fetch('./api/whoami',{credentials:'same-origin'});const a=await r.json();if(a.user){S.authUser=a.user;S.accountName=a.user.nickname;if(a.profile)profile={...initialProfile(),...a.profile};render();}}catch{}}
""")
old="${act('▣ CRÉER UN PROFIL LOCAL','profileEdit','outline')}${act(S.sound?'♫ SON ACTIVÉ':'♪ SON COUPÉ','audio','outline')}"
new="${!S.authUser?`${act('CRÉER UN COMPTE','authRegister','primary')}${act('SE CONNECTER','authLogin','outline')}`:`${act('DÉCONNEXION','authLogout','outline')}`} ${act('PSEUDONYME LOCAL','profileEdit','outline')}${act(S.sound?'♫ SON ACTIVÉ':'♪ SON COUPÉ','audio','outline')}"
assert old in s;s=s.replace(old,new)
s=s.replace("${S.accountPane?`<form id=\"localProfileForm\"", "${S.accountPane?`<form id=\"localProfileForm\"")
s=s.replace("<p class=\"v51-profile-note\">Les comptes cloud et le multijoueur distant nécessitent une authentification serveur avant publication.</p></section>", "${S.authUser?`<p class=\"v51-profile-note\">✓ Connecté : ${esc(S.authUser.email)} · données sauvegardées sur le serveur lorsque celui-ci est actif.</p>`:`<p class=\"v51-profile-note\">Sans serveur : le jeu fonctionne en invité. Les comptes nécessitent de lancer npm start.</p>`}</section>")
# show auth form in profile before note via placeholder
pfx='${S.authUser?`<p class="v51-profile-note"'
pos=s.find(pfx);assert pos>0
s=s[:pos]+'''${S.authForm?`<form id="authForm" class="v51-local-profile"><h3>${S.authForm==='register'?'CRÉER UN COMPTE':'CONNEXION'}</h3>${S.authForm==='register'?`<label>PSEUDO<input name="nickname" minlength="2" maxlength="24" required placeholder="Pseudo"></label>`:''}<label>E-MAIL<input name="email" type="email" required placeholder="email@exemple.fr"></label><label>MOT DE PASSE<input name="password" type="password" minlength="10" required placeholder="10 caractères minimum"></label><button type="submit" class="btn primary">${S.authForm==='register'?'S’INSCRIRE':'SE CONNECTER'}</button><small>Un serveur Node démarré avec npm start est requis. Les identifiants ne sont pas conservés dans le navigateur.</small>${S.authError?`<strong class="v51-auth-error">${esc(S.authError)}</strong>`:''}</form>`:''}''' +s[pos:]
s=s.replace("app.addEventListener('submit',e=>{if(e.target.id==='localProfileForm')", "app.addEventListener('submit',async e=>{if(e.target.id==='authForm'){e.preventDefault();const f=e.target.elements;try{const r=await authRequest(S.authForm==='register'?'register':'login',{email:f.email.value,password:f.password.value,nickname:f.nickname?.value||''});S.authUser=r.user;S.accountName=r.user.nickname;S.authError='';S.authForm=null;if(r.profile)profile={...initialProfile(),...r.profile};else persist();render();notice('COMPTE CONNECTÉ');}catch(err){S.authError=err.message;render();}return;}if(e.target.id==='localProfileForm')")
s=s.replace("if(key==='profileEdit'){S.accountPane=!S.accountPane;render();return;}", "if(key==='profileEdit'){S.accountPane=!S.accountPane;render();return;}\n if(key==='authRegister'||key==='authLogin'){S.authError='';S.authForm=key==='authRegister'?'register':'login';S.accountPane=false;render();return;}\n if(key==='authLogout'){authRequest('logout',{}).catch(()=>{});S.authUser=null;S.authForm=null;S.accountName=storeGet('localStorage','ki_account_name','');try{profile={...initialProfile(),...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch{profile=initialProfile();}render();return;}")
s=s.replace("render();\n\nif('serviceWorker'", "render();loadAccount();\n\nif('serviceWorker'")
p.write_text(s)
print('accounts patched')
